    const extreme = JSON.stringify({
      name: 'Extreme',
      agents: [
        {
          name: 'Test',
          role: 'copywriter',
          personality: {
            sliders: {
              'bold-subtle': -10,
              'playful-serious': 99,
              'experimental-conventional': 0,
              'verbose-concise': 0,
              'warm-corporate': 0,
            },
          },
          traits: [],
          customPrompt: '',
        },
      ],
    })
    const team = parseAITeamResponse(extreme)
    expect(team).not.toBeNull()
